// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor who calls addToBalance and a deposit amount
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a reasonable wide range but allow zero as well
        vm.assume(actor != address(0));
        // bound amount to max less than type max to avoid peculiar overflows in tests
        amount = bound(amount, 0, type(uint128).max);

        // record previous balance for actor
        uint256 prev = c.getBalance(actor);

        // fund the actor externally so they can send ETH
        vm.deal(actor, amount);

        // perform the payable call as the actor
        vm.prank(actor);
        // call addToBalance with value 'amount'
        try c.addToBalance{value: amount}() {
            // call succeeded
        } catch {
            // if it reverts, still record that behavior via assertion below
        }

        uint256 after = c.getBalance(actor);

        // General rule: for the correct contract, after == prev + amount
        // (i.e., balance increases by exactly the deposited msg.value)
        // We assert that holds. The mutant that writes zero instead of adding
        // will fail this assertion for some inputs (amount > 0).
        assertTrue(after == prev + amount);
    }
}

