        // fund the actor so they can send `amount`
        vm.deal(actor, amount);

        // record previous balance via getter
        uint256 beforeBal = c.getBalance(actor);

        // perform the deposit from actor
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // single assertion: after calling addToBalance, the stored balance for the caller
