// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: depositor `depositor`, observed key `observed`, and deposit `amount`.
    // General rule: for any addresses depositor and observed and any deposit amount >= 0,
    // after depositor calls addToBalance with `amount`, the stored balance for `observed` is
    // >= its previous value. The reference obeys this (balances only increase on deposits);
    // the mutant that writes zero or subtracts can violate non-decrease for some inputs.
    function testFuzz_property(address depositor, address observed, uint256 amount) public {
        // keep domains wide but sensible: avoid zero-address for depositor to allow vm.prank/deal
        if (depositor == address(0)) depositor = address(1);
        // observed can be any address (including depositor)
        // bound amount to something reasonable to avoid overflows in the test environment
        amount = bound(amount, 0, 1 ether);

        // fund depositor so they can send `amount`
        vm.deal(depositor, amount);

        // record previous balance for observed key
        uint256 before = c.getBalance(observed);

        // perform deposit as depositor
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // record after
        uint256 after = c.getBalance(observed);

        // The universal property we assert: the observed stored balance never decreases after any deposit by any actor.
        // This holds for the correct contract for all inputs; the mutant that zeroes/subtracts may violate it for some inputs.
        assertTrue(after >= before);
    }
}

