pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, address observed, uint256 amount) public {
        // keep addresses non-zero to be meaningful and amount bounded to avoid overflow issues in vm.deal
        vm.assume(depositor != address(0));
        vm.assume(observed != address(0));
        // fund depositor so it can send `amount`
        uint256 bounded = bound(amount, 0, type(uint64).max);
        vm.deal(depositor, bounded);

        // record observed balance before
        uint256 beforeBal = c.getBalance(observed);

        // perform deposit from depositor
        vm.prank(depositor);
        // call addToBalance with value `bounded`
        // capture whether call succeeded (should succeed on reference)
        bool ok;
        try c.addToBalance{value: bounded}() {
            ok = true;
        } catch {
            ok = false;
        }

        // read observed balance after
        uint256 afterBal = c.getBalance(observed);

        // General rule: deposit never decreases ANY observed account's stored balance
        // (this holds for the reference contract for all inputs; the mutant that zeroes msg.value breaks it)
        assertTrue(afterBal >= beforeBal);
    }
}

