pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker address (will be a contract we deploy) and an amount
    function testFuzz_property(address fuzzed, uint256 amount) public {
        // keep amount in a reasonable range but wide
        amount = bound(amount, 1, 1 ether);

        // Deploy an attacker contract that will attempt reentrancy in receive()
        Attacker attacker = new Attacker(c);

        // fund the attacker so it can call addToBalance with value
        vm.deal(address(attacker), amount);

        // record balance before
        uint256 before = c.getBalance(address(attacker));

        // have attacker call addToBalance sending `amount`
        attacker.doAdd{value: amount}();

        // After the (single) external call completes, the reference contract guarantees
        // that the caller's balance increased by exactly `amount`.
        uint256 after = c.getBalance(address(attacker));

        // Single assertion: reference always satisfies `after == before + amount` for all inputs;
        // the mutant (which removes the require check) can be made to fail for some inputs
        // because reentrancy during the modifier may allow inconsistent update/withdraw.
        assertTrue(after == before + amount);
    }
}

// Minimal adversarial helper: tries a reentrant withdraw during its receive to exploit missing guard.
contract Attacker {
    C public target;
    bool public attacked;

    constructor(C _target) {
        target = _target;
        attacked = false;
    }

    // entry point used by the test to invoke addToBalance on target
    function doAdd() external payable {
        // call target.addToBalance with this contract as msg.sender (we are already this)
        // using low-level call is unnecessary; direct call suffices
        target.addToBalance{value: msg.value}();
    }

    // receive will try to reenter target.withdrawBalance once to trigger inconsistent state
    receive() external payable {
        // only attempt once to avoid infinite recursion
        if (!attacked) {
            attacked = true;
            // attempt to withdraw which may trigger a reentrant sequence if the modifier is broken
            // we ignore success/failure
            try target.withdrawBalance() {
            } catch {
            }
        }
    }
}

