pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint96 depositAmount) public {
        // keep depositor as a non-zero address and depositAmount > 0
        vm.assume(depositor != address(0));
        depositAmount = uint96(bound(depositAmount, 1, type(uint96).max));

        // Deploy an attacker that will try to reenter during the low-level call in withdrawBalance
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Give depositor and attacker some ETH
        vm.deal(depositor, uint256(depositAmount));
        vm.deal(address(attacker), 1 ether);

        // depositor deposits to their balance
        vm.prank(depositor);
        c.addToBalance{value: uint256(depositAmount)}();

        // Ensure depositor's stored balance equals deposit (reference contract invariant)
        uint256 depositorBalance = c.getBalance(depositor);
        assertTrue(depositorBalance == uint256(depositAmount));

        // Now have attacker deposit a small amount so attacker has a stored balance as well
        uint256 attackerDeposit = 1 wei;
        vm.prank(address(attacker));
        c.addToBalance{value: attackerDeposit}();

        // At this point, on the correct contract a subsequent addToBalance by the attacker
        // should not be able to reenter and alter depositor's stored balance when attacker later withdraws.
        // We will trigger attacker.withdraw which will call c.withdrawBalance() from the attacker, whose
        // fallback will attempt to reenter c.addToBalance and try to manipulate state only possible if
        // the require(!locked_) guard is missing.

        // Attacker attempts to withdraw; capture depositor balance after the attacker's withdraw completes
        attacker.attackWithdraw();

        // Single assertion: depositor's balance (observed via public getter) remains equal to original deposit
        // On the correct contract this holds for all inputs; on the mutant (require removed) there exist inputs
        // where attacker reentrantly alters/depletes depositor's balance and this assertion fails.
        assertTrue(c.getBalance(depositor) == uint256(depositAmount));
    }
}

// Minimal reentrant attacker: on receiving ETH via call from C.withdrawBalance, it will try to reenter
// by calling addToBalance on C, attempting to manipulate stored balances while C may be in a bad locked state.
contract ReentrantAttacker {
    C public target;
    bool public attacked;
    constructor(address _t) payable {
        target = C(_t);
        attacked = false;
    }

    // Initiate withdraw which will call target.withdrawBalance from this contract
    function attackWithdraw() public {
        // call withdrawBalance on target to trigger the low-level call to this contract
        target.withdrawBalance();
    }

    // Fallback invoked when C sends ETH to this contract during withdrawBalance
    receive() external payable {
        if (!attacked) {
            attacked = true;
            // attempt to reenter addToBalance (send 0 value) to change storage in presence of broken guard
            // This call is meant to be benign but can trigger state inconsistencies in mutant
            target.addToBalance{value: 0}();
        }
    }
}

