pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: attacker deposit amount and victim initial balance (both uint96 in original failure report but keep wide)
    function testFuzz_property(address attackerAddr, uint96 attackerDeposit, uint96 victimInitial) public {
        // Keep addresses valid and distinct and amounts reasonable
        vm.assume(attackerAddr != address(0));
        vm.assume(attackerAddr != address(this));
        // ensure some non-zero deposit to make attacker able to trigger behavior
        attackerDeposit = uint96(bound(attackerDeposit, 1, type(uint96).max));
        victimInitial = uint96(bound(victimInitial, 0, type(uint96).max));

        // Deploy attacker helper contract from attackerAddr
        vm.deal(attackerAddr, uint256(attackerDeposit));
        // Prepare a victim account and fund its recorded balance in c by making a deposit
        address victim = address(0xBEEF);
        vm.deal(victim, uint256(victimInitial));

        // First, victim funds its userBalance by calling addToBalance with victimInitial (if >0)
        if (victimInitial > 0) {
            vm.prank(victim);
            c.addToBalance{value: uint256(victimInitial)}();
        }

        // Record victim's stored balance before the adversarial interaction
        uint256 beforeVictimBalance = c.getBalance(victim);

        // Deploy a reentrant attacker contract (its constructor records c and victim for use)
        vm.prank(attackerAddr);
        Attacker attacker = new Attacker(c, victim);

        // Fund attacker EOA so it can send value
        vm.deal(address(attacker), uint256(attackerDeposit));

        // Have the attacker call addToBalance on c sending attackerDeposit. The attacker contract's receive()
        // will attempt to re-enter c.withdrawBalance during the external call in withdraw path if allowed by mutant.
        // We call through the attacker contract so reentrancy can be executed from its fallback/receive.
        bool ok;
        try attacker.callAdd{value: uint256(attackerDeposit)}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the operation, on the correct contract, the victim's stored balance must be unchanged
        // (the reference prevents reentrancy that could alter victim balance during another's addToBalance)
        uint256 afterVictimBalance = c.getBalance(victim);

        // Single assertion: reference guarantees victim's balance unchanged for all admissible inputs;
        // the mutant (without the require) permits a reentrant attacker to change victim's balance for some inputs,
        // causing this assertion to fail on the mutant and pass on the reference.
        assertTrue(afterVictimBalance == beforeVictimBalance);
    }
}

// Minimal attacker that re-enters during a payable call back to c
contract Attacker {
    C public c;
    address public victim;

    constructor(C _c, address _victim) payable {
        c = _c;
        victim = _victim;
    }

    // Called by test to initiate addToBalance from this contract
    function callAdd() external payable {
        // Call c.addToBalance from this contract, sending the ETH forwarded to this call
        c.addToBalance{value: msg.value}();
    }

    // When this contract receives ETH (during c's external calls), attempt to drain victim by calling withdrawBalance
    receive() external payable {
        // Try to withdraw victim's balance by calling withdrawBalance (this will attempt to send to victim via low-level call)
        // We call withdrawBalance to attempt to trigger behavior that could alter stored balances when reentrancy guard is broken.
        // Ignore failures; if mutant allows reentrancy this can change storage in c.
        try c.withdrawBalance() {
            // noop
        } catch {
            // noop
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    // Fuzz parameters:
    // - depositor: the EOA that will call addToBalance and send ether
    // - attackerDeposit: amount to fund the attacker so it can perform reentrant behavior
    // - depositsCount: number of distinct other victims to pre-fund (keeps domain wide)
    function testFuzz_property(address depositor, uint96 attackerDeposit, uint8 depositsCount) public {
        // Keep domains wide but sensible
        vm.assume(depositor != address(0));
        uint96 max = type(uint96).max;
        if (attackerDeposit == 0) attackerDeposit = 1; // ensure attacker has some funds to operate
        if (attackerDeposit > max / 1000) attackerDeposit = uint96(max / 1000);
        // bound depositsCount to avoid too-gas-heavy loops while keeping variety
        depositsCount = depositsCount % 8; // up to 7 victims

        // 1) Pre-fund several victim accounts by directly calling addToBalance from those accounts
        address[] memory victims = new address[](depositsCount);
        for (uint8 i = 0; i < depositsCount; i++) {
            address victim = address(uint160(uint256(keccak256(abi.encodePacked("victim", i)))));
            victims[i] = victim;
            vm.deal(victim, 1 ether);
            vm.prank(victim);
            c.addToBalance{value: 1 ether}();
        }

        // 2) Compute total stored sum before attacker action
        uint256 totalBefore = 0;
        for (uint8 i = 0; i < depositsCount; i++) {
            totalBefore += c.getBalance(victims[i]);
        }
        // also include attacker's own stored balance (likely zero)
        totalBefore += c.getBalance(address(attacker));

        // 3) Fund attacker externally so it can perform reentrancy during depositor's deposit
        vm.deal(address(attacker), attackerDeposit);

        // 4) Make attacker configured to target the first victim (if any), else itself
        address targetVictim = depositsCount > 0 ? victims[0] : address(attacker);
        attacker.configure(targetVictim);

        // 5) depositor performs a deposit but routes the external interaction such that the attacker
        //    can be triggered (attacker will attempt to re-enter C during the external call if allowed).
        // We simulate that by having depositor send value to attacker first, which in its fallback will call into C.
        // This models an external party getting control during the deposit flow in presence of an unchecked reentrancy guard.
        uint256 depositorValue = 0.5 ether;
        vm.deal(depositor, depositorValue + 1 ether);

        // The depositor will send funds to the attacker contract which in turn will call addToBalance on C
        // to attempt to manipulate balances while C's nonReentrant_ modifier is in-flight in the mutant.
        vm.prank(depositor);
        // send to attacker which in its receive will call c.addToBalance{value: attackerDepositAttempt}()
        (bool sent,) = address(attacker).call{value: depositorValue}(
            abi.encodeWithSignature("triggerFromEOA(uint256)", attackerDeposit)
        );
        // we don't assert on sent; the key invariant is about accounting stored inside C

        // 6) After the sequence, compute total stored sum again
        uint256 totalAfter = 0;
        for (uint8 i = 0; i < depositsCount; i++) {
            totalAfter += c.getBalance(victims[i]);
        }
        totalAfter += c.getBalance(address(attacker));
        totalAfter += c.getBalance(depositor);

        // The general rule: In the correct contract, the sum of userBalance entries for all involved accounts
        // equals the cumulative deposits these accounts made via addToBalance (we approximated by sum before plus the depositorValue
        // and any attackerDeposit that legitimately got recorded). Because we cannot read internal cumulative deposits history,
        // we assert a conservation-style property: totalAfter >= totalBefore (no stored balances are lost by reentrancy during the depositor's call).
        // The correct contract with working nonReentrant_ never loses stored balances during addToBalance, so totalAfter >= totalBefore.
        // The mutant can allow reentrant draining which can make totalAfter < totalBefore for some fuzzed inputs.

        assertTrue(totalAfter >= totalBefore);
    }
}

// Minimal adversarial helper that on receiving funds will attempt to re-enter C and call addToBalance to try to manipulate victim balances.
contract Attacker {
    C public c;
    address public target;
    constructor(C _c) payable {
        c = _c;
    }

    function configure(address _target) public {
        target = _target;
    }

    // Called by depositor via a low-level call with encoded attackerDeposit.
    // This function will forward some value back into C via addToBalance in the same call flow to simulate reentrancy window.
    function triggerFromEOA(uint256 attackerDeposit) external payable {
        // On being called, immediately call into C.addToBalance sending a small amount (if we have funds) to try to affect balances
        uint256 toSend = attackerDeposit > 0 && address(this).balance >= attackerDeposit ? attackerDeposit : address(this).balance;
        if (toSend > 0) {
            // try to re-enter addToBalance and credit target (attacker chooses its own msg.sender by calling from this contract)
            // This will call addToBalance on C with 'this' as msg.sender, affecting c.userBalance(address(this)).
            // If C is vulnerable (modifier missing require), this call may occur during another external call and cause inconsistent accounting.
            c.addToBalance{value: toSend}();
        }
    }

    // Allow contract to receive Ether
    receive() external payable {}
}

