pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attacker initial deposit and reentrant callback deposit size
    function testFuzz_property(uint256 initialDeposit, uint256 reentryDeposit) public {
        // keep amounts reasonable but wide; require >0 so Ether is actually sent
        initialDeposit = bound(initialDeposit, 1, 1 ether);
        reentryDeposit = bound(reentryDeposit, 1, 1 ether);

        // deploy attacker helper that will re-enter c.addToBalance during receive()
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund attacker EOA so it can send txs
        vm.deal(address(attacker), initialDeposit + reentryDeposit);

        // 1) attacker deposits initialDeposit into c via addToBalance
        attacker.deposit{value: initialDeposit}();

        // record balance as seen by c after the first deposit
        uint256 before = c.getBalance(address(attacker));

        // sanity: before should equal initialDeposit under correct contract
        // Now trigger the attacker to perform a deposit that during its receive will re-enter
        // It will call addToBalance with reentryDeposit and during the external call re-enter
        // The mutant (no lock) allows reentrancy to create inconsistent final balance
        attacker.triggerReentrantDeposit{value: reentryDeposit}(reentryDeposit);

        // Single assertion: after these operations, the on-chain stored balance for attacker
        // must equal the sum of the two deposits. The reference contract's nonReentrant_ ensures
        // this holds for all inputs; the mutant removing the lock can be exploited so this may fail.
        assertTrue(c.getBalance(address(attacker)) == before + reentryDeposit);
    }
}

// Minimal reentrant attacker: on receive(), call back into c.addToBalance to try to exploit lack of lock
contract ReentrantAttacker {
    C immutable target;
    bool reentered;
    constructor(C _t) payable {
        target = _t;
        reentered = false;
    }

    // simple deposit wrapper
    function deposit() external payable {
        // call addToBalance normally
        target.addToBalance{value: msg.value}();
    }

    // trigger a deposit that will cause reentry during the low-level call path in C
    function triggerReentrantDeposit(uint256 amount) external payable {
