pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor and amounts. The adversarial counterparty is a reentrant attacker
    // deployed below; we still fuzz the depositor address and the deposit amounts.
    function testFuzz_property(address depositor, uint128 depositAmount, uint128 attackerDeposit) public {
        // Keep addresses usable
        vm.assume(depositor != address(0));
        // Keep attackerDeposit and depositAmount non-zero and reasonably bounded to avoid overflow of test harness.
        uint256 amt = uint256(depositAmount) % 1 ether; // keep within 0..1 ether-1
        uint256 atkAmt = uint256(attackerDeposit) % 1 ether;
        // Need a distinct attacker address (we will deploy Attacker contract and use its address)
        // Deploy attacker helper and fund both depositor and attacker contract
        Attacker atk = new Attacker(address(c));

        // fund depositor and attacker contract
        vm.deal(depositor, amt + 1 wei);
        vm.deal(address(atk), atkAmt + 1 wei);

        // depositor makes a deposit
        if (amt > 0) {
            vm.prank(depositor);
            c.addToBalance{value: amt}();
        }
        // attacker funds its balance in target contract
        if (atkAmt > 0) {
            // make the attacker contract deposit into c so it has a recorded balance
            atk.fund{value: atkAmt}();
        }

        // Now trigger withdrawBalance from depositor but route the external call target to the attacker
        // The attacker will reenter when it receives funds. To cause the difference, we have the depositor
        // call withdrawBalance while the attacker is a different contract that may reenter during other's withdraw.

        // We perform withdrawBalance as the depositor. If the attacker's receive reenters in a way that
        // manipulates balances, the mutant (which zeroes after external call) can leave depositor's balance non-zero.

        bool ok;
        vm.startPrank(depositor);
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // General property to assert: after a depositor calls withdrawBalance, the depositor's recorded balance is zero
        // (the correct contract C enforces this for all inputs); the buggy mutant that zeroes after external call can
        // leave the depositor's balance non-zero for some inputs (when reentrancy occurs).
        assertTrue(c.getBalance(depositor) == 0);
    }
}

// Minimal reentrant attacker: when it receives Ether it will try to reenter withdrawBalance on target
contract Attacker {
    C target;
    constructor(address _t) {
        target = C(_t);
    }
    // allow funding this contract and then deposit into target
    receive() external payable {
        // On receiving funds, try to reenter target.withdrawBalance(); ignore failures
        // Use low-level call to avoid violating test constraints; reentrancy will only matter if target is vulnerable.
        (bool s, ) = address(target).call(abi.encodeWithSignature("withdrawBalance()"));
        s; // silence
    }
    function fund() external payable {
        // deposit into target so this contract has a recorded balance
        target.addToBalance{value: msg.value}();
    }
}
